------------ import ------------
local KTool = CS.Engine.Lib.KTool
------------ import ------------
local worldBossComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.WorldBossComponent)
local UITeamMembersNode = "Game.UI.FightTeam.UITeamMembersNode.UITeamMembersNode"

---@class UIWorldBossUpCardNode        
---@field Text                          	UnityEngine.RectTransform               
---@field btnInfo                       	UnityEngine.RectTransform               
---@field UITeamMembersNode             	UnityEngine.RectTransform               
local UIWorldBossUpCardNode = Class('UIWorldBossUpCardNode')

function UIWorldBossUpCardNode:__init()
    self._curBossPlanVo = nil        --当前bossVo
end

function UIWorldBossUpCardNode:__delete()
    self._curBossPlanVo = nil        --当前bossVo
end

function UIWorldBossUpCardNode:Awake()
    SetButtonAction(self.btnInfo, Bind(self, self.OnBtnInfo))
    local id = worldBossComponent:GetCurBossPlanId()
    if not id then
        return
    end
    self._curBossPlanVo = QuestConfMgr:GetInstance():GetWorldBossPlanVo(id)
    if not self._curBossPlanVo then
        return
    end
    self:FillUpCardInfo()
end

--绘制up角色
function UIWorldBossUpCardNode:FillUpCardInfo()
    local t, _t = QuestConfMgr:GetInstance():GetWorldBossUpData(self._curBossPlanVo.UpGroup)
    if not t or table.count(t) <= 0 then
        return
    end

    local scr = CfUtils.GetLuaScr(self.UITeamMembersNode, UITeamMembersNode)
    if scr then
        scr:RefreshCardBase(t, nil)
        scr:RefreshSpacing(-20)
    end

    local str = ""
    for k, v in pairs(t) do
        local vo = CardConfMgr:GetInstance():GetCardByRefId(v.cardId)
        local name = vo.name ~= nil and vo.name or ""
        str = str..name.."    "..QuestConfMgr:GetInstance():GetDataBuffDesc(v).."\n"
    end
    self._desc = str
end

function UIWorldBossUpCardNode:OnBtnInfo()
    GameUtils.ShowCommonTipsBoard(self.btnInfo, localize("引导者"), self._desc)
end

function UIWorldBossUpCardNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIWorldBossUpCardNode
